/// <summary>
/// PricingAttribute of table <c>LogisticsPostalAddress</c> field CountryRegionId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeLogisticsPostalAddressCountryRegionId extends UPSPricingAttributeLogisticsPostalAddress implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(LogisticsPostalAddress, CountryRegionId);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    LogisticsPostalAddress logisticsPostalAddress;

    while select logisticsPostalAddress
        group by CountryRegionId
    {
        if (! ret.in(logisticsPostalAddress.CountryRegionId))
        {
            ret.add(logisticsPostalAddress.CountryRegionId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(LogisticsPostalAddress, CountryRegionId));
    qbr.value(queryValue(_value));
}
